package modelo;
import config.Conexion; import java.sql.*; import java.util.*;
public class ServicioDAO {
    public int agregar(Servicio s){String q="INSERT INTO Servicio(nombre_servicio,descripcion,id_estado) VALUES(?,?,1)"; try(Connection c=new Conexion().crearConexion(); PreparedStatement p=c.prepareStatement(q)){p.setString(1,s.getNombreServicio());p.setString(2,s.getDescripcion());return p.executeUpdate();}catch(Exception e){System.out.println("ERROR SERVICIO AGREGAR: "+e.getMessage());return 0;}}
    public int editar(Servicio s){String q="UPDATE Servicio SET nombre_servicio=?, descripcion=? WHERE id_servicio=?"; try(Connection c=new Conexion().crearConexion(); PreparedStatement p=c.prepareStatement(q)){p.setString(1,s.getNombreServicio());p.setString(2,s.getDescripcion());p.setInt(3,s.getIdServicio());return p.executeUpdate();}catch(Exception e){System.out.println("ERROR SERVICIO EDITAR: "+e.getMessage());return 0;}}
    public int eliminar(int id){String q="UPDATE Servicio SET id_estado=0 WHERE id_servicio=?"; try(Connection c=new Conexion().crearConexion(); PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);return p.executeUpdate();}catch(Exception e){System.out.println("ERROR SERVICIO ELIMINAR: "+e.getMessage());return 0;}}
    public Servicio buscar(int id){String q="SELECT * FROM Servicio WHERE id_servicio=?"; try(Connection c=new Conexion().crearConexion(); PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id); ResultSet r=p.executeQuery(); if(r.next()) return map(r);}catch(Exception e){System.out.println("ERROR SERVICIO BUSCAR: "+e.getMessage());}return null;}
    public List<Servicio> listar(){List<Servicio> l=new ArrayList<>();String q="SELECT * FROM Servicio WHERE id_estado=1 ORDER BY nombre_servicio"; try(Connection c=new Conexion().crearConexion(); PreparedStatement p=c.prepareStatement(q); ResultSet r=p.executeQuery()){while(r.next())l.add(map(r));}catch(Exception e){System.out.println("ERROR SERVICIO LISTAR: "+e.getMessage());}return l;}
    private Servicio map(ResultSet r)throws SQLException{Servicio s=new Servicio();s.setIdServicio(r.getInt("id_servicio"));s.setNombreServicio(r.getString("nombre_servicio"));s.setDescripcion(r.getString("descripcion"));s.setIdEstado(r.getInt("id_estado"));return s;}
}
